CREATE TABLE user_profiles (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, profile_version BIGINT UNSIGNED NOT NULL, profile_status VARCHAR(16) NOT NULL, status_reason VARCHAR(64), grade VARCHAR(30), preferred_content_modes_json JSON, recent_focus_json JSON, profile_data_json JSON, preferred_explanation_style VARCHAR(50), learning_pace VARCHAR(20), summary_profile TEXT, algorithm_version VARCHAR(30), confidence DECIMAL(4,3), last_event_at DATETIME(3), last_processed_event_id BIGINT UNSIGNED NOT NULL DEFAULT 0, computed_at DATETIME(3), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
 PRIMARY KEY(id), UNIQUE KEY uk_user_profiles_user_id(user_id), CONSTRAINT chk_user_profiles_version CHECK(profile_version>=0), CONSTRAINT chk_user_profiles_status CHECK(profile_status IN ('READY','NOT_READY','STALE')), CONSTRAINT chk_user_profiles_confidence CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1), CONSTRAINT chk_user_profiles_learning_pace CHECK(learning_pace IS NULL OR learning_pace IN ('slow','moderate','fast')), CONSTRAINT chk_user_profiles_summary_profile_length CHECK(summary_profile IS NULL OR CHAR_LENGTH(summary_profile)<=16383), CONSTRAINT chk_user_profiles_ready_or_stale CHECK(profile_status NOT IN ('READY','STALE') OR (profile_version>=1 AND profile_data_json IS NOT NULL AND JSON_TYPE(profile_data_json) = 'OBJECT' AND algorithm_version IS NOT NULL AND TRIM(algorithm_version)<>'' AND computed_at IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
